        <!-- Expand More button -->
        <button id="expandMore">Expand More</button>
      </div>
    `;

    // Find elements by slot
    const headerEl = this.shadowRoot.querySelector('[name="header"]');
    const introEl = this.shadowRoot.querySelector('[name="intro"]');
    const detailsEl = this.shadowRoot.querySelector('[name="details"]');
    const btn = this.shadowRoot.getElementById('expandMore');

    // Initial state: collapsed (not open)
    this._isOpen = false;

    // Attach button handler
    if (btn) {
      btn.addEventListener('click', () => this.toggle());
    }
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (name === 'slot-header') {
      // Nothing special, we keep the same structure
    }
  }

  toggle() {
    if (this._isOpen) {
      // Closing
      this._isOpen = false;
      this.updateHeaderIcon('-');
      this.hideIntro();
      this.hideDetails();
    } else {
      // Opening
      this._isOpen = true;
      this.updateHeaderIcon('-');
      this.showIntro();
      this.showDetails();
    }
  }

  // Helper to update the icon (plus/minus) in header
  updateHeaderIcon(icon) {
    const header = this.shadowRoot.querySelector('[name="header"]');
    const iconSpan = header.querySelector('.toggle-icon');
    if (iconSpan) {
      iconSpan.textContent = icon;
    }
  }

  // Show intro content (clear previous)
  showIntro() {
    const intro = this.shadowRoot.querySelector('[name="intro"]');
    intro.innerHTML = '';
  }

  // Hide intro content
  hideIntro() {
    const intro = this.shadowRoot.querySelector('[name="intro"]');
    intro.innerHTML = '';
  }

  // Show details content
  showDetails() {
    const details = this.shadowRoot.querySelector('[name="details"]');
    details.innerHTML = '';
  }

  // Hide details content
  hideDetails() {
    const details = this.shadowRoot.querySelector('[name="details"]');
    details.innerHTML = '';
  }

  // Ensure button exists and updates label
  updateButtonText() {
    const btn = this.shadowRoot.getElementById('expandMore');
    if (btn) {
      btn.textContent = this._isOpen ? 'Collapse More' : 'Expand More';
    }
  }
}

