    const introEl = this.shadowRoot.querySelector('[slot="intro"]');
    const detailsEl = this.shadowRoot.querySelector('[slot="details"]');
    const btn = this.shadowRoot.getElementById('expandMore');

    // Store original content for later restoration.
    this._headerContent = headerEl ? headerEl.innerHTML : '';
    this._introContent = introEl ? introEl.innerHTML : '';
    this._detailsContent = detailsEl ? detailsEl.innerHTML : '';

    // Initial state: collapsed (not open)
