      // Going to close
      this._isOpen = false;
      this.headerEl.classList.add('x-details-header--closed');
      this._introEl.innerHTML = '';
      this._detailsEl.innerHTML = '';
    } else {
      // Going to open
      this._isOpen = true;
      this.headerEl.classList.add('x-details-header--open');
      this._introEl.innerHTML = this._introContent;
      this._detailsEl.innerHTML = this._detailsContent;
