class XDetails extends HTMLElement {
  static get observedAttributes() {
    return [];
  }

  connectedCallback() {
    this.shadowRoot.innerHTML = `
      <div class="x-details-wrapper">
        <span class="x-details-header" slot="header"><span class="toggle-icon">+</span> Header here</span>
        <div class="x-details-intro" slot="intro">intro part always visible</div>
        <div class="x-details-details" slot="details">details part - visible when expanded</div>
        <button id="expandMore">Expand More</button>
      </div>
    `;

    const headerEl = this.shadowRoot.querySelector('.x-details-header');
    const introEl = this.shadowRoot.querySelector('.x-details-intro');
    const detailsEl = this.shadowRoot.querySelector('.x-details-details');
    const btn = this.shadowRoot.getElementById('expandMore');

    this._headerContent = headerEl ? headerEl.innerHTML : '';
    this._introContent = introEl ? introEl.innerHTML : '';
    this._detailsContent = detailsEl ? detailsEl.innerHTML : '';

    this._isOpen = false; // start collapsed

    if (btn) {
      btn.addEventListener('click', () => this.toggle());
    }
  }

  attributeChangedCallback() {}

  toggle() {
    const newIsOpen = !this._isOpen;
    if (newIsOpen) {
      // Opening
      this._isOpen = true;
      this.headerEl.classList.add('x-details-header--open');
      this._introEl.innerHTML = ''; // hide intro
      this._detailsEl.innerHTML = this._detailsContent; // show details
    } else {
      // Closing
      this._isOpen = false;
      this.headerEl.classList.add('x-details-header--closed');
      this._introEl.innerHTML = this._introContent; // show intro
      this._detailsEl.innerHTML = ''; // hide details
    }
    this.updateButtonLabel();
  }

  updateHeaderIcon(icon) {
    const headerEl = this.shadowRoot.querySelector('.x-details-header');
    const iconSpan = headerEl.querySelector('.toggle-icon');
    if (iconSpan) {
      iconSpan.textContent = icon;
      iconSpan.classList.add(`x-details-header--${icon}`);
    }
  }

  updateButtonLabel() {
    const btn = this.shadowRoot.getElementById('expandMore');
    if (btn) {
      btn.textContent = this._isOpen ? 'Collapse More' : 'Expand More';
    }
  }
}

customElements.define('x-details', XDetails);
